package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type decl struct {
	file     string
	line     int
	receiver string
	sig      string
}

func main() {
	var decls []decl
	backendRoots := []string{"cmd", "internal", "server", "store", "proto"}
	root := "."
	for _, br := range backendRoots {
		_ = filepath.Walk(filepath.Join(root, br), func(path string, info os.FileInfo, err error) error {
			if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") {
				return nil
			}
			fset := token.NewFileSet()
			f, err := parser.ParseFile(fset, path, nil, 0)
			if err != nil {
				return nil
			}
			for _, decl := range f.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok || fn.Recv == nil || fn.Name.Name != "Close" {
					continue
				}
				recv := fn.Recv.List[0].Type
				recvStr := strings.TrimSpace(strings.ReplaceAll(string(fset.File(fn.Pos()).Text()[fn.Recv.Pos()-fn.Pos():fn.Recv.End()-fn.Pos()]), "\n", " "))
				// simpler receiver formatting
				switch t := recv.(type) {
				case *ast.StarExpr:
					if id, ok := t.X.(*ast.Ident); ok {
						recvStr = "*" + id.Name
					}
				case *ast.Ident:
					recvStr = t.Name
				default:
					recvStr = "?"
				}
				// fix: get receiver var name + type properly
				field := fn.Recv.List[0]
				var recvName string
				if len(field.Names) > 0 {
					recvName = field.Names[0].Name
				}
				switch t := field.Type.(type) {
				case *ast.StarExpr:
					if id, ok := t.X.(*ast.Ident); ok {
						recvStr = fmt.Sprintf("(%s *%s)", recvName, id.Name)
					}
				case *ast.Ident:
					recvStr = fmt.Sprintf("(%s %s)", recvName, t.Name)
				}
				sig := "Close()"
				if fn.Type.Results != nil && len(fn.Type.Results.List) > 0 {
					sig = "Close() error"
				}
				pos := fset.Position(fn.Pos())
				decls = append(decls, decl{path, pos.Line, recvStr, sig})
			}
			return nil
		})
	}
	sort.Slice(decls, func(i, j int) bool {
		if decls[i].file != decls[j].file {
			return decls[i].file < decls[j].file
		}
		return decls[i].line < decls[j].line
	})
	fmt.Printf("COUNT=%d\n", len(decls))
	for _, d := range decls {
		fmt.Printf("%s:%d: func %s %s\n", d.file, d.line, d.receiver, d.sig)
	}
}
